SELECT IFNULL(SUM(dataTable.today_all),0) AS todayAll, IFNULL(SUM(dataTable.today_complete),0) AS todayComplete, IFNULL(SUM(dataTable.false_complete_num),0) AS falseCompleteNum, IFNULL(SUM(dataTable.judge_num),0) AS judgeNum, IFNULL(SUM(dataTable.dispatch_num),0) AS dispatchNum, IFNULL(SUM(dataTable.grab_num),0) AS grabNum, IFNULL(SUM(dataTable.handle_num),0) AS handleNum, IFNULL(SUM(dataTable.approve_num),0) AS approveNum, IFNULL(SUM(dataTable.order_complete_num),0) AS orderCompleteNum, IFNULL(SUM(dataTable.repeat_complete_num),0) AS repeatCompleteNum, IFNULL(SUM(dataTable.false_num),0) AS falseNum, IFNULL(SUM(dataTable.real_num),0) AS realNum, IFNULL(SUM(dataTable.false_num),0) + IFNULL(SUM(dataTable.real_num),0) AS allNum FROM vm_statistics_event_num_day dataTable
and DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(NOW() ,'%Y-%m-%d')
AND dataTable.create_date >= #{param.queryStartTime} AND dataTable.create_date <= #{param.queryEndTime}
AND dataTable.province_id = #{param.provinceId}
AND dataTable.city_id = #{param.cityId}
AND dataTable.county_id = #{param.countyId}
${param.dataScope}

SELECT IFNULL(SUM(dataTable.yesterday_all),0) AS yesterdayAll
FROM vm_statistics_event_num_yesterday dataTable


        and DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(NOW() ,'%Y-%m-%d')


        AND dataTable.create_date >= #{param.queryStartTime}
        AND dataTable.create_date <= #{param.queryEndTime}


        AND dataTable.province_id = #{param.provinceId}


        AND dataTable.city_id = #{param.cityId}


        AND dataTable.county_id = #{param.countyId}

    ${param.dataScope}

SELECT IFNULL(SUM(dataTable.today_all),0) AS allNum,IFNULL(SUM(dataTable.ai_num),0) AS AINum,
IFNULL(SUM(dataTable.manual_num),0) AS manNum,IFNULL(SUM(dataTable.onekey_num),0) AS keyNum
FROM vm_statistics_event_num_day dataTable


        AND DATE_FORMAT(dataTable.create_date ,'%Y') = DATE_FORMAT(NOW() ,'%Y')


        AND DATE_FORMAT(dataTable.create_date ,'%Y-%m') = DATE_FORMAT(NOW() ,'%Y-%m')


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(DATE_SUB(NOW(),interval 1 DAY) ,'%Y-%m-%d')


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(NOW() ,'%Y-%m-%d')


        AND dataTable.create_date >= #{param.queryStartTime}
        AND dataTable.create_date <= #{param.queryEndTime}


        AND dataTable.province_id = #{param.provinceId}


        AND dataTable.city_id = #{param.cityId}


        AND dataTable.county_id = #{param.countyId}


        and dataTable.tenant_id = #{param.tenantId}

    ${param.dataScope}

SELECT sum(order_num) as orderNum,warning_source as warningSource
FROM vm_statistics_event_source dataTable


        AND DATE_FORMAT(dataTable.create_date ,'%Y') = DATE_FORMAT(NOW() ,'%Y')


        AND DATE_FORMAT(dataTable.create_date ,'%Y-%m') = DATE_FORMAT(NOW() ,'%Y-%m')


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(DATE_SUB(NOW(),interval 1 DAY) ,'%Y-%m-%d')


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(NOW() ,'%Y-%m-%d')


        AND dataTable.create_date  >=  #{param.queryStartTime}


        AND dataTable.create_date  <=  #{param.queryEndTime}


        AND dataTable.province_id = #{param.provinceId}


        AND dataTable.city_id = #{param.cityId}


        AND dataTable.county_id = #{param.countyId}


        and dataTable.tenant_id = #{param.tenantId}

    ${param.dataScope}

group by warning_source

SELECT dataTable.warning_type_id typeId,SUM(dataTable.warning_num) num,
SUM(dataTable.ai_num) aiNum, SUM(dataTable.judge_num) judgeNum, SUM(dataTable.real_num) realNum,
SUM(dataTable.false_num) falseNum
FROM vm_statistics_event_type dataTable


        AND DATE_FORMAT(dataTable.create_date ,'%Y') = DATE_FORMAT(NOW() ,'%Y')


        AND DATE_FORMAT(dataTable.create_date ,'%Y-%m') = DATE_FORMAT(NOW() ,'%Y-%m')


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(DATE_SUB(NOW(),interval 1 DAY) ,'%Y-%m-%d')


        AND DATE_FORMAT(dataTable.create_date,'%Y-%m-%d') = DATE_FORMAT(NOW() ,'%Y-%m-%d')


        AND dataTable.create_date >= #{param.queryStartTime}
        AND dataTable.create_date <= #{param.queryEndTime}


        AND dataTable.province_id = #{param.provinceId}


        AND dataTable.city_id = #{param.cityId}


        AND dataTable.county_id = #{param.countyId}

    ${param.dataScope}

GROUP BY dataTable.warning_type_id
ORDER BY num DESC,typeId DESC

SELECT sum(device_num) deviceNum, province_id code FROM vm_statistics_devices_tt WHERE province_id in
#{item.code}
AND `year` = YEAR(NOW()) AND `month` = MONTH(NOW()) AND `day` = DAY(NOW()) group by province_id

SELECT sum(device_num) deviceNum, city_id code FROM vm_statistics_devices_tt WHERE city_id in
#{item.code}
AND `year` = YEAR(NOW()) AND `month` = MONTH(NOW()) AND `day` = DAY(NOW()) group by city_id

